INSERT INTO `actividades` (`id`, `evento_id`, `titulo`, `tipo`, `descripcion`, `fecha`, `hora`, `lugar`, `precio_extra`, `requiere_entrada_online`, `enlace_venta`, `es_gratis`, `imagen`, `created_at`, `updated_at`) VALUES
(530, 1, 'Tope Nocturno', 'Tope', 'Disfruta del tradicional tope nocturno como parte de las actividades de la Expo San Carlos Internacional. Este evento reúne caballos, música y ambiente festivo para toda la familia. Incluida con la entrada general a la Expo (evento gratuito dentro del recinto)', '2026-04-16', '19:00:00', 'Campo ferial - Parte Trasera', 0.00, 0, NULL, 1, '[\"/assets/uploads/upload-1775883031619-894469616.jpg\"]', '2026-04-21 01:39:33', '2026-04-21 01:39:33'),
(531, 1, 'Festival de Bandas', 'Festival', 'Te esperamos el próximo 17 de abril a las 5:00 P.M. ¡No te perdás este espectáculo increíble que inicia con desfile por el campo ferial y finaliza con un show en El Ring, con las mejores bandas del país: Banda Comunal de La Fortuna, Banda 506, Banda de Zarcero y La Banda de Platanar de Florencia', '2026-04-17', '17:00:00', 'Campo ferial - Expo San Carlos Internacional', 0.00, 0, NULL, 1, '[\"/assets/uploads/upload-1775898633605-169295706.jpg\"]', '2026-04-21 01:39:33', '2026-04-21 01:39:33'),
(532, 1, 'Concierto Kapo', 'concierto', 'Disfruta del concierto de Kapo en la Expo San Carlos Internacional. Al adquirir tu entrada a través de Smarticket, podrás disfrutar no solo del concierto, sino también del acceso al campo ferial.Los niños menores de +12 años SOLO en la Gramilla VIP de menores, deben de estar acompañado de un encargado legal, NO SE PERMITE EL CONSUMO DE LICOR en la Gramilla VIP de menores y mayores de +18 años se les tiene PROHIBIDO la entrada a la Gramilla VIP de menores.Con la compra de la entrada del concierto de kapo, usted podra disfrutar del resto de enventos del campo ferial (no incluye parqueo)', '2026-04-18', '18:00:00', 'Campo ferial - Parte Trasera', 0.00, 1, 'https://smarticket.net', 0, '[\"/assets/images/ExpoSanCarlos2026/ExpoSanCarlosKapo2026.jpeg\",\"/assets/uploads/upload-1775967157999-895144965.png\",\"/assets/uploads/upload-1775968532433-322219732.jpeg\",\"/assets/uploads/upload-1775969523102-464248423.jpeg\"]', '2026-04-21 01:39:33', '2026-04-21 01:39:33'),
(533, 1, 'Concierto Los Karkis', 'concierto', 'Disfruta en vivo del concierto de Los Karkis, una agrupación reconocida por su música tropical que pondrá a bailar a todos los asistentes en la Expo San Carlos Internacional.🎟️ Entrada:Evento gratuito con la compra de la entrada general al campo ferial. No tiene costo adicional.', '2026-04-24', '19:00:00', 'Campo ferial - Parte Trasera', 0.00, 0, NULL, 1, '[\"/assets/images/ExpoSanCarlos2026/ExpoSanCarlosLosKarkis2026.jpeg\"]', '2026-04-21 01:39:33', '2026-04-21 01:39:33'),
(534, 1, 'Tope Nacional', 'Tope', 'Disfruta del tradicional Tope Nacional de la Expo San Carlos Internacional, uno de los eventos más esperados, donde participan caballistas de todo el país en un ambiente lleno de cultura, tradición y entretenimiento.Si deseas disfrutar de una mejor experiencia, puedes reservar un espacio exclusivo para ver el evento con mayor comodidad.📞 Reservaciones:8473-6292🎟️ Entrada:Incluida con la entrada general a la Expo', '2026-04-25', '13:00:00', 'Entrada del Campo Ferial', 0.00, 0, NULL, 1, '[\"assets/images/ExpoSanCarlos2026/TopeInternacionalExpo2026.jpg\"]', '2026-04-21 01:39:33', '2026-04-21 01:39:33'),
(535, 1, 'Verano Toreado', 'rodeo', 'Verano toreado de su teletica', '2026-04-25', '20:00:00', 'Redondel de la Expo San Carlos Internacional', 0.00, 0, NULL, 0, '[\"assets\\\\images\\\\ExpoSanCarlos2026\\\\Expositores2026\\\\verandoToreadoExpo2026.jpg\"]', '2026-04-21 01:39:33', '2026-04-21 01:39:33');

