(1, NULL, 'aprobado', NULL, '2026-04-15 03:46:29', 'expo-san-carlos-internacional-2026', 'Expo San Carlos Internacional 2026', 'Los Festejos Populares de Abangares ya se sienten en el ambiente 💃🐂\n\n📅 ABRIL 2026\n📍 Abangares, Guanacaste\n\nTradición, cultura, toros, música, desfiles y mucha fiesta nos esperan 🙌', '2026-04-16', '2026-04-27', 'Cámara de Ganaderos San Carlos, Platanar, Alajuela, Costa Rica', '/assets/images/ExpoSanCarlos2026/ExpoSanCarlosLogo2026.jpeg', 1, '/assets/images/ExpoSanCarlos2026/ExpoSanCarlosHorarioGeneral2026.jpeg', '<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d5753.723471566428!2d-84.46625556251665!3d10.440400752165207!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x8fa07036dc9a7551%3A0x71aae73e035ab310!2sC%C3%A1mara%20de%20Ganaderos%20de%20San%20Carlos!5e1!3m2!1ses-419!2scr!4v1775694355473!5m2!1ses-419!2scr\" width=\"100%\" height=\"350\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\"></iframe>', '<iframe src=\"https://embed.waze.com/iframe?zoom=16&lat=10.620545&lon=-85.457509&ct=livemap\" width=\"600\" height=\"450\" allowfullscreen></iframe>', 'gratis', NULL, '#ff00b3', '#000000', '#dedede', '#ff0000', 'rgba(62, 42, 31, 0.6)', '#ffffff', '#ffffff', '#b000c7', '#ffffff', '2026-04-09 19:09:46', '2026-04-21 01:39:33', '#000000', 'Alajuela', '#000000', '#ffffff', '#ffffff', '#000000', '#ffffff', '#000000', '#0e0aff', '#000000', '#ffffff', '#000000', '#000000', NULL, '#ffffff', '2026-04-16 19:10:37', NULL, '#eeeeee', '#ffffff', '#2c1a0e', 0, NULL, '#2c1a0e', 1);

