(215, 1, 'Chicharrones y Parrillada Vindas', 'Toldos', 'CHICHARRONES Y PARRILLADA VINDAS 🔥 ¡VOLVEMOS! 🔥Por segundo año consecutivo estaremos en Expo San Carlos 🤩Vení a disfrutar de:🥓 Los mejores chicharrones🍖 La mejor costilla bbq🌯 Nuestro súper cono mixto… ¡una verdadera delicia!😎 Y sí… somos los mejores(No lo decimos nosotros… ¡lo dicen ustedes!)📍 Te esperamos en Expo San Carlos🔥 ¡No te quedés sin probarlos!', '-no especifica-', 0, '[\"/assets/uploads/upload-1776312164517-803129485.png\"]', NULL, NULL, '2026-04-21 01:39:33', '2026-04-21 01:39:33'),
(216, 1, 'El Chante Imperial', 'Comidas y Bebidas', 'Los mejores eventos en Expo San Carlos los encontrarás en El Chante.•Los Ajenos.•Gimario DJ Chaves.•Vara Blanca Band •La Kuarta-DJ Tokio.•Toledo.•La Cámara del Despecho (Ramzi-Kike-Arlenne E)•Jose Fuentes-Rey G.•Matiz.🗣No te lo puedes perder.', '-no especifica-', 0, '[\"/assets/uploads/upload-1776312213255-80169801.png\",\"/assets/uploads/upload-1776312218993-778399243.png\"]', NULL, NULL, '2026-04-21 01:39:33', '2026-04-21 01:39:33');

